+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      statusMessage.textContent = "";
+
+      const isValid = Object.keys(fields).every((name) => validateField(name));
+
+      if (!isValid) {
+        statusMessage.textContent = "Please fix the highlighted fields and try again.";
+        return;
+      }
+
+      statusMessage.textContent = "Thanks — your message is ready to send.";
+      form.reset();
+      Object.keys(fields).forEach((name) => setError(name, ""));
+    });
+  </script>
+</body>
+</html>
