 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: rgba(255, 255, 255, 0.92);
       --border: #d9e2ef;
       --text: #132238;
       --muted: #5f6b7a;
       --primary: #2563eb;
       --primary-hover: #1d4ed8;
       --error: #b42318;
       --error-bg: #fff1f0;
       --shadow: 0 20px 60px rgba(16, 24, 40, 0.12);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, #e8f0ff 0, transparent 35%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .support-card {
       width: 100%;
       max-width: 560px;
       background: var(--card);
       border: 1px solid rgba(217, 226, 239, 0.75);
       border-radius: 24px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(12px);
       padding: 32px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       font-size: 0.875rem;
       font-weight: 600;
       color: var(--primary);
       margin: 0 0 10px;
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(1.75rem, 3vw, 2.25rem);
       line-height: 1.1;
     }

     .subtitle {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-size: 0.95rem;
       font-weight: 600;
     }

     input {
       width: 100%;
       border: 1px solid var(--border);
       border-radius: 14px;
       padding: 14px 16px;
       font: inherit;
       color: var(--text);
       background: #fff;
       outline: none;
       transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
     }

     input::placeholder {
       color: #97a3b6;
     }

     input:focus {
       border-color: rgba(37, 99, 235, 0.55);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
     }

     .helper-text {
       margin: 0;
       font-size: 0.875rem;
       color: var(--muted);
     }

     .error-message {
       min-height: 1.2em;
       margin: 0;
       font-size: 0.875rem;
       color: var(--error);
     }

     .form-field.is-invalid input {
       border-color: rgba(180, 35, 24, 0.55);
       background: var(--error-bg);
     }

     button {
       margin-top: 6px;
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, var(--primary), #4f46e5);
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
       transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
     }

     button:hover {
       transform: translateY(-1px);
       background: linear-gradient(135deg, var(--primary-hover), #4338ca);
     }

     button:focus {
       outline: none;
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.16), 0 12px 24px rgba(37, 99, 235, 0.22);
     }

     .form-status {
       margin: 8px 0 0;
       min-height: 1.2em;
       font-size: 0.95rem;
       color: var(--primary);
     }

     @media (max-width: 640px) {
       .support-card {
         padding: 24px;
         border-radius: 20px;
       }
     }
   </style>
 </head>
 <body>
   <main class="support-card">
     <p class="eyebrow">Support</p>
     <h1>Contact our team</h1>
     <p class="subtitle">Send a message and we’ll get back to you as soon as possible.</p>

     <form id="contact-form" novalidate>
       <div class="form-field" id="name-field">
         <label for="full-name">Full name</label>
         <input
           id="full-name"
           name="fullName"
           type="text"
           placeholder="Jane Doe"
           autocomplete="name"
           required
           aria-describedby="full-name-error"
         />
         <p class="error-message" id="full-name-error" aria-live="polite"></p>
       </div>

       <div class="form-field" id="email-field">
         <label for="email-address">Email address</label>
         <input
           id="email-address"
           name="email"
           type="email"
           placeholder="jane@example.com"
           autocomplete="email"
           required
           aria-describedby="email-error"
         />
         <p class="error-message" id="email-error" aria-live="polite"></p>
       </div>

       <div class="form-field" id="phone-field">
         <label for="phone-number">Phone number</label>
         <input
           id="phone-number"
           name="phone"
           type="tel"
           placeholder="+1 (555) 123-4567"
           autocomplete="tel"
           aria-describedby="phone-helper phone-error"
         />
         <p class="helper-text" id="phone-helper">Expected format: +1 (555) 123-4567</p>
         <p class="error-message" id="phone-error" aria-live="polite"></p>
       </div>

       <button type="submit">Send message</button>
       <p class="form-status" id="form-status" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById("contact-form");
     const statusMessage = document.getElementById("form-status");

     const fields = {
       fullName: {
         input: document.getElementById("full-name"),
         field: document.getElementById("name-field"),
         error: document.getElementById("full-name-error"),
         validate(value) {
           return value.trim() ? "" : "Full name is required.";
         }
       },
       email: {
         input: document.getElementById("email-address"),
         field: document.getElementById("email-field"),
         error: document.getElementById("email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }

           return fields.email.input.validity.valid ? "" : "Enter a valid email address.";
         }
       },
       phone: {
         input: document.getElementById("phone-number"),
         field: document.getElementById("phone-field"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }

           const allowedCharacters = /^\+?[0-9\s().-]+$/;
           const digitCount = trimmed.replace(/\D/g, "").length;

           if (!allowedCharacters.test(trimmed) || digitCount < 7) {
             return "Enter a valid phone number, like +1 (555) 123-4567.";
           }

